<script setup lang="ts">import { computed,shallowRef } from "vue";import { ChevronDown,ChevronUp } from "lucide-vue-next";import type { CatalogoTipoEquipoImpacto } from "@/stores/dbequipos/engrase/catalogo/aceitesCatalogo.types";const props=defineProps<{items:readonly CatalogoTipoEquipoImpacto[]}>();const expanded=shallowRef(false);const ordered=computed(()=>[...props.items].sort((a,b)=>b.cantidadEquipos-a.cantidadEquipos||a.nombre.localeCompare(b.nombre,"es",{sensitivity:"base"})));const visible=computed(()=>expanded.value?ordered.value:ordered.value.slice(0,4));const remaining=computed(()=>Math.max(ordered.value.length-4,0));</script>
<template><section aria-labelledby="oil-equipment-title"><h3 id="oil-equipment-title" class="text-xs font-semibold text-gray-800">Usado en tipos de equipo</h3><p v-if="!items.length" class="mt-2 text-xs text-gray-500">Sin equipos asociados</p><div v-else class="mt-2 flex flex-wrap gap-1.5"><span v-for="item in visible" :key="item.id" class="inline-flex items-center gap-2 rounded-md bg-main/6 px-2 py-1.5 text-xs text-main">{{item.nombre}}<strong>{{new Intl.NumberFormat('es').format(item.cantidadEquipos)}}</strong></span><button v-if="remaining||expanded" class="inline-flex min-h-8 cursor-pointer items-center gap-1 rounded-md border border-main/15 px-2 text-xs font-semibold text-main" :aria-expanded="expanded" @click="expanded=!expanded">{{expanded?'Ver menos':`+${remaining}`}}<component :is="expanded?ChevronUp:ChevronDown" class="h-3.5 w-3.5" /></button></div></section></template>
